pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller, address other) public {
        // Restrict to realistic amounts and distinct addresses
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        vm.assume(caller != other);
        vm.assume(caller != address(0) && other != address(0));
        vm.assume(caller != address(this) && other != address(this));

        // Deposit using the fallback (msg.sender gets balance)
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // Also deposit to 'other' to keep total sum nontrivial
        vm.deal(other, 1 ether);
        vm.prank(other);
        (bool ok2,) = address(c).call{value: 1 ether}("");
        require(ok2, "deposit2 failed");

        // Record total sum of all balances before withdrawal
        uint256 sumBefore = c.balances(caller) + c.balances(other);

        // Withdraw from caller
        vm.prank(caller);
        bool withdrawSuccess;
        try c.withdraw() { withdrawSuccess = true; } catch { withdrawSuccess = false; }

        // Total sum after withdrawal
        uint256 sumAfter = c.balances(caller) + c.balances(other);

        // Rule: if withdraw succeeded, sum must decrease by withdrawAmount.
        // If withdrawal reverted (unlikely in this scenario), sum stays unchanged.
        if (withdrawSuccess) {
            // For correct contract, caller balance becomes 0, sum decreases by withdrawAmount.
            // Buggy contract leaves balance unchanged, so sum stays same: violation.
            assertTrue(sumAfter == sumBefore - withdrawAmount);
        } else {
            assertTrue(sumAfter == sumBefore);
        }
    }
}

