pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialDeposit, uint256 reenterAmount) public {
        // Restrict to admissible range: deposit > 0 and reenter <= deposit to ensure funds exist
        vm.assume(initialDeposit > 0 && initialDeposit <= type(uint128).max);
        vm.assume(reenterAmount > 0 && reenterAmount <= initialDeposit);

        // Deploy a reentrant attacker that calls withdraw() again during receive
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), reenterAmount);

        // Fund the attacker and make initial deposit
        vm.deal(address(attacker), initialDeposit);
        attacker.deposit{value: initialDeposit}();

        // Record pre-state: attacker balance and total balance sum
        uint256 preAttackerBalance = c.balances(address(attacker));
        uint256 preTotalSum = c.balances(address(attacker)); // only one depositor

        // Execute withdraw — may be reentrant
        attacker.attack();

        // Post-state
        uint256 postAttackerBalance = c.balances(address(attacker));
        uint256 postTotalSum = c.balances(address(attacker));

        // General invariant: total sum of balances after call >= pre-sum minus (pre-attacker balance - post-attacker balance)
        // i.e., the net reduction in total balances should not exceed the reduction in attacker's own balance.
        // If reentrancy allows double-spend, total sum drops by more than attacker's balance reduction.
        assertTrue(postTotalSum >= preTotalSum - (preAttackerBalance - postAttackerBalance));
    }
}

