pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 attackAmount) public {
        // Admissible domain: amounts within reasonable range so deposits don't overflow
        vm.assume(amount > 0 && amount <= 1 ether);
        vm.assume(attackAmount > 0 && attackAmount <= 1 ether);
        // The adversary is a re-entrant attacker that calls withdraw again on receive
        Attacker attacker = new Attacker(c, attackAmount);
        vm.deal(address(attacker), attackAmount);
        // Deposit funds into c for attacker
        vm.prank(address(attacker));
        (bool depositOk,) = address(c).call{value: attackAmount}("");
        require(depositOk, "deposit failed");
        // Record balances sum and total withdrawn before withdraw
        uint256 sumBefore = c.balances(address(attacker));
        for (uint256 i = 1; i < 10; i++) {
            address a = vm.addr(i);
            sumBefore += c.balances(a);
        }
        uint256 withdrawnBefore = address(attacker).balance; // attacker's ETH balance pre-attack
        // Execute attack: attacker withdraws its own balance, re-enters, drains more
        vm.prank(address(attacker));
        attacker.attack();
        // Record balances sum after withdraw
        uint256 sumAfter = c.balances(address(attacker));
        for (uint256 i = 1; i < 10; i++) {
            address a = vm.addr(i);
            sumAfter += c.balances(a);
        }
        uint256 withdrawnAfter = address(attacker).balance;
        // The invariant: sum of balances + total ether withdrawn (i.e., what the contract owes + what was paid)
        // should be at least as large as before. In the reference, sum never decreases plus withdrawn increases.
        // More precisely: sumBefore + withdrawnBefore <= sumAfter + withdrawnAfter
        assertTrue(sumBefore + withdrawnBefore <= sumAfter + withdrawnAfter);
    }
}

