contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(depositAmount > 0);
        // Bound to prevent overflow in total computation.
        depositAmount = bound(depositAmount, 1, 1 ether);

        // Deposit
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = c.balances(depositor);
        uint256 contractBalBefore = address(c).balance;

        // Withdraw
        vm.prank(depositor);
        c.withdraw();

        uint256 balanceAfter = c.balances(depositor);
        uint256 contractBalAfter = address(c).balance;

        // Invariant: depositor's balance after successful withdraw must be 0.
        // This holds for the reference (because it transfers the full balance),
        // but fails for the mutant when depositAmount != 1, because the transfer sends only 1 wei
        // and the user's balance is forcefully set to 0, leaking Ether in the contract.
        assertTrue(balanceAfter == 0);
    }
}

