        vm.assume(amount > 0 && amount < 1 ether);
        vm.assume(user != address(0) && user != address(c));

        // Fund user and deposit into the contract
        vm.deal(user, amount);
        vm.prank(user);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        // Record pre-state
