pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrancyAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrancyAttacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);

        // fund attacker
        vm.deal(address(attacker), amount);
        // attacker deposits into C
        attacker.deposit{value: amount}();

        // record pre-state invariant
        uint256 totalSupplyBefore = totalTrackedBalance();
        uint256 ethBefore = address(c).balance;
        assertEq(totalSupplyBefore, ethBefore);

        // attacker triggers withdraw that reenters
        vm.prank(address(attacker));
        attacker.attackWithdraw();

        // after attack, invariant must still hold for correct contract
        uint256 totalSupplyAfter = totalTrackedBalance();
        uint256 ethAfter = address(c).balance;
        assertEq(totalSupplyAfter, ethAfter);
    }

    function totalTrackedBalance() internal view returns (uint256) {
        // attacker is the only depositor; its balance is public
        return c.balances(address(attacker));
    }
}

contract ReentrancyAttacker {
    C public target;
    uint256 public depth;

    constructor(C _target) {
        target = _target;
    }

    function deposit() external payable {
        // trigger fallback to record balance
        (bool ok, ) = address(target).call{value: msg.value}("");
        require(ok);
    }

    function attackWithdraw() external {
        target.withdraw();
    }

    receive() external payable {
        if (depth == 0 && address(target).balance > 0) {
            depth++;
            target.withdraw();
            depth--;
        }
    }
}

